import { Order, Page } from './types';

export interface CursorPosition {
  createdAt: string;
  id: string;
}

export function parseCursor(cursor: unknown): CursorPosition {
  if (typeof cursor !== 'string') {
    throw new Error('invalid request');
  }
  const parts = cursor.split('|');
  if (parts.length !== 2 || parts[0].length === 0 || parts[1].length === 0) {
    throw new Error('invalid request');
  }
  return { createdAt: parts[0], id: parts[1] };
}

function compareOrders(a: Order, b: Order): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

function isAfterCursor(order: Order, cursor: CursorPosition): boolean {
  if (order.createdAt !== cursor.createdAt) {
    return order.createdAt > cursor.createdAt;
  }
  return order.id > cursor.id;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string): Order[] {
    // filter/sort operate on a fresh array; the input array and rows are never mutated.
    return this.rows.filter(row => row.tenant === tenant).sort(compareOrders);
  }

  listPage(tenant: string, limit: number, cursor?: string): Page {
    if (!tenant || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new Error('invalid request');
    }
    const position = cursor === undefined ? null : parseCursor(cursor);

    // Filtering happens before any pagination: the cursor is only a boundary
    // over the already tenant-filtered, sorted set (even if its row is gone).
    const matching = this.list(tenant);

    let start = 0;
    if (position !== null) {
      const index = matching.findIndex(row => isAfterCursor(row, position));
      start = index === -1 ? matching.length : index;
    }

    const items = matching.slice(start, start + limit);
    const hasMore = items.length === limit && start + items.length < matching.length;
    const nextCursor = hasMore
      ? `${items[items.length - 1].createdAt}|${items[items.length - 1].id}`
      : null;
    return { items, nextCursor };
  }
}
